/**
 * Browser speech-synthesis fallback narrator.
 *
 * Voices, pacing and pronunciation depend on the browser and operating
 * system. Speech is spoken cue by cue as playback reaches each subtitle, so
 * sync is approximate (scene/cue level), never word-perfect. Speech output
 * is generated by the OS and cannot be captured into an exported video.
 */

export const speechSupported = (): boolean =>
  typeof window !== 'undefined' && 'speechSynthesis' in window && typeof SpeechSynthesisUtterance !== 'undefined';

let speechLang = 'en';
/** Language used to pick browser voices ('en', 'it', …). */
export const setSpeechLanguage = (lang: string) => {
  speechLang = lang;
};

/** Browser voices for the narration language, natural-sounding ("Natural", "Neural", "Google") first. */
export function languageVoices(lang = speechLang): SpeechSynthesisVoice[] {
  if (!speechSupported()) return [];
  const quality = (v: SpeechSynthesisVoice) => (/natural|neural|online|google|premium|enhanced/i.test(v.name) ? 1 : 0);
  return window.speechSynthesis
    .getVoices()
    .filter((v) => v.lang.toLowerCase().startsWith(lang))
    .sort((a, b) => quality(b) - quality(a) || a.name.localeCompare(b.name));
}

/** Calls `cb` now and whenever the voice list changes. Returns an unsubscribe function. */
export function watchVoices(cb: (voices: SpeechSynthesisVoice[]) => void, lang = 'en'): () => void {
  if (!speechSupported()) {
    cb([]);
    return () => {};
  }
  const handler = () => cb(languageVoices(lang));
  handler();
  window.speechSynthesis.addEventListener('voiceschanged', handler);
  // Some browsers populate voices late without firing the event.
  const timer = window.setTimeout(handler, 800);
  return () => {
    window.clearTimeout(timer);
    window.speechSynthesis.removeEventListener('voiceschanged', handler);
  };
}

export class SpeechNarrator {
  private spokenCueId: string | null = null;

  /** Speak a cue once. Returns false if speech is unavailable. */
  speakCue(id: string, text: string, voiceURI: string | null, rate: number): boolean {
    if (!speechSupported()) return false;
    if (this.spokenCueId === id) return true;
    this.spokenCueId = id;
    this.speak(text, voiceURI, rate);
    return true;
  }

  speak(text: string, voiceURI: string | null, rate: number) {
    if (!speechSupported()) return;
    const u = new SpeechSynthesisUtterance(text);
    const voices = languageVoices();
    const voice = voices.find((v) => v.voiceURI === voiceURI) ?? voices.find((v) => v.default) ?? voices[0];
    if (voice) {
      u.voice = voice;
      u.lang = voice.lang;
    } else {
      u.lang = speechLang;
    }
    u.rate = Math.min(2, Math.max(0.5, rate));
    u.pitch = 0.9;
    window.speechSynthesis.speak(u);
  }

  /** Stop speaking and forget which cue was spoken (used on pause and seek). */
  cancel() {
    this.spokenCueId = null;
    if (speechSupported()) window.speechSynthesis.cancel();
  }
}
